// PATCH v1.0.11-instant-loader: клик показывает спиннер МГНОВЕННО;
// hide — только когда реальный запрос завершён (см. перехват fetch ниже).
// Страховка: если за 120 сек ни один сетевой вызов так и не завершился —
// спрятать, чтобы спиннер не «завис» навечно.
document.addEventListener('click', function(e) {
    var t = e.target.closest(SEL);
    if (!t) return;
    if (t.disabled) return;
    if (t.dataset && t.dataset.noLoader === '1') return;
    _showLoader(t.getAttribute('data-loader-label') || 'Сохранение…');
    window.__trkClickGuardAt = Date.now();
    clearTimeout(window.__trkClickGuardTimer);
    window.__trkClickGuardTimer = setTimeout(function(){
        if (_reqCount > 0 && Date.now() - (window.__trkLastFetchEndAt || 0) > 60000) _hideLoader();
    }, 120000);
}, true);

/* ============================================================
   PATCH v1.0.11-instant-loader — ЕДИНЫЙ ПЕРЕХВАТЧИК window.fetch
   ------------------------------------------------------------
   Любое нажатие «Сохранить/Создать/Удалить» в любой модалке должно
   МГНОВЕННО показывать спиннер и держать его до конца сетевого
   запроса. Раньше это работало только для apiJson(): десятки мест
   (retry-циклы, прямые fetch в плагином коде и обработчиках) шли
   мимо счётчика _reqCount, а watchdog гасил спиннер через 8 секунд
   на медленной сети. Теперь учитываются ВСЕ мутационные запросы.
   Совместимо с патчем v1.0.10-hours-hh-mm-display (тот же guard).
   ============================================================ */
(function(){
'use strict';
if (window.__trkInstantLoaderV1011) return;
window.__trkInstantLoaderV1011 = true;

var nf = window.__trkNativeFetch || window.fetch;
if (!nf || nf.__trkInstantWrapped) return;
window.__trkNativeFetch = nf;

function isMut(m){ m = (m || 'GET').toUpperCase(); return m !== 'GET' && m !== 'HEAD' && m !== 'OPTIONS'; }

function labelFor(u, m){
    u = String(u || '');
    if (u.indexOf('/log/save') !== -1 || u.indexOf('/api/log') !== -1) return 'Сохранение отметки…';
    if (u.indexOf('/task/save') !== -1 || u.indexOf('/api/task') !== -1) return 'Сохранение задачи…';
    if (u.indexOf('/api/settings') !== -1) return 'Сохранение настроек…';
    if (m === 'DELETE') return 'Удаление…';
    return 'Сохранение…';
}

function wrapped(input, opts){
    var url = (typeof input === 'string' || typeof input === 'URL') ? input : (input && input.url) || '';
    var method = (opts && opts.method) || (input && input.method) || 'GET';
    if (!isMut(method)) return nf.apply(null, arguments);
    var shown = false;
    try {
        if (typeof _showLoader === 'function') { _showLoader(labelFor(url, method)); shown = true; }
    } catch (e) {}
    var settled = false;
    function done(){
        if (settled) return; settled = true;
        try { window.__trkLastFetchEndAt = Date.now(); } catch (e2) {}
        try { if (shown && typeof _hideLoader === 'function') _hideLoader(); } catch (e3) {}
    }
    var p;
    try { p = nf.apply(null, arguments); }
    catch (e) { done(); throw e; }
    if (!p || typeof p.then !== 'function') { done(); return p; }
    return p.then(function(r){ done(); return r; }, function(err){ done(); throw err; });
}
wrapped.__trkInstantWrapped = true;
window.fetch = wrapped;
try { console.log('%c[instant-loader] v1.0.11: перехват fetch активен', 'color:#2ecc71;font-weight:bold'); } catch (e) {}
})();

"""plugins/assigned_today.py - 📌 Назначено на день."""
__version__ = '1.4'
__description__ = ('📌 Назначено на день: режимы «Все задачи» / «Отмеченные сегодня», '
                   'чекбоксы выбора задач для выгрузки в Excel, фильтр по гипотезе/заданию '
                   'сотрудника (item-level assignees + hyp_item_id), отметка пунктов '
                   'гипотез прямо из плагина (PATCH v1.0.9)')

import json
from datetime import date, datetime, timedelta
from io import BytesIO
from flask import jsonify, request, Response, redirect, send_file

try:
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    _HAS_XLSX = True
except ImportError:
    _HAS_XLSX = False

_JS = "(function(){'use strict';window.fmtHoursHM=function(h){h=Number(h)||0;var neg=h<0?'-':'';var tm=Math.round(Math.abs(h)*60);var hh=Math.floor(tm/60),mm=tm-hh*60;if(hh===0&&mm===0)return '0 ч.';if(mm===0)return neg+hh+' ч.';if(hh===0)return neg+mm+' мин.';return neg+hh+' ч. '+mm+' мин.';};function r(){if(typeof window.__trkRegisterPlugin!=='function'){setTimeout(r,200);return;}window.__trkRegisterPlugin({id:'assigned_today',icon:'📌',name:'Назначено на день',url:'/plugins/assigned_today/',perm:''});}r();})();"

TASK_STATUS_LABELS = {'active': 'Активна', 'done': 'Выполнена',
                      'paused': 'Приостановлена', 'archived': 'Архив'}
HYP_STATUS_LABELS = {'planned': '⏳ План', 'in_progress': '🔄 В работе',
                     'done': '✅ Готово', 'failed': '❌ Не подтв.'}
JOB_STATUS_LABELS = {'planned': '⏳', 'in_progress': '🔄', 'done': '✅', 'failed': '❌'}


def _valid_date(s):
    try:
        datetime.strptime(s, '%Y-%m-%d')
        return True
    except Exception:
        return False


def _task_active_on(t, dk):
    st = (t.get('status') or '').strip()
    if st not in ('active', 'paused'):
        return False
    sd = (t.get('start_date') or '').strip()
    dl = (t.get('deadline') or '').strip()
    if sd and dk < sd:
        return False
    if dl and dk > dl:
        return False
    return True


def _tree_raw(t):
    raw = t.get('hypotheses')
    if raw is None:
        try:
            raw = json.loads(t.get('hypotheses_json') or '[]')
        except Exception:
            raw = []
    return raw if isinstance(raw, list) else []


def _job_children(raw, hid):
    """Задания гипотезы hid: плоский формат (kind/parent)."""
    out = []
    for tk in raw:
        if not isinstance(tk, dict):
            continue
        if tk.get('kind') == 'task' and tk.get('parent') == hid:
            out.append(tk)
    return out


def _hyp_items_map(t):
    """Дерево гипотез задачи -> {item_id: item}. Понимает плоский формат
    [{kind:'hypothesis'|'task', parent}] и вложенный [{...,tasks:[...]}]."""
    out = {}
    for h in _tree_raw(t):
        if not isinstance(h, dict):
            continue
        hid = str(h.get('id', '') or '').strip()
        if hid and hid not in out:
            out[hid] = h
        ch = h.get('tasks')
        if isinstance(ch, list):
            for tk in ch:
                if isinstance(tk, dict):
                    kid = str(tk.get('id', '') or '').strip()
                    if kid and kid not in out:
                        out[kid] = tk
    return out


def _hyp_parent_of(tree, item_id):
    """Id гипотезы-родителя для задания из вложенного формата ('' если нет)."""
    try:
        for h in tree or []:
            if not isinstance(h, dict):
                continue
            ch = h.get('tasks')
            if isinstance(ch, list):
                for tk in ch:
                    if isinstance(tk, dict) and str(tk.get('id', '') or '').strip() == item_id:
                        return str(h.get('id', '') or '').strip()
    except Exception:
        return ''
    return ''


def _last_status_for(logs, emp_id, task_id, hyp_item_id):
    """Последний статус отметки сотрудника по пункту гипотезы
    (hyp_item_id='' — отметка без привязки к пункту)."""
    best = None
    try:
        for l in logs or []:
            if l.get('task_id') != task_id:
                continue
            if (l.get('employee_id') or '') != emp_id:
                continue
            if (l.get('hyp_item_id') or '') != (hyp_item_id or ''):
                continue
            key = (str(l.get('date') or ''), int(l.get('id') or 0))
            cur = (str(best.get('date') or ''), int(best.get('id') or 0)) if best else ('', -1)
            if best is None or key > cur:
                best = l
    except Exception:
        return ''
    return str((best or {}).get('status') or '')


def _norm_hours(x):
    try:
        return float(x or 0)
    except (TypeError, ValueError):
        return 0.0


def _assign_hyp_items(t, eid):
    """Пункты дерева гипотез, на которые назначен сотрудник eid.
    Возвращает ([{item,parent}], filtered), где filtered=True означает,
    что у дерева есть item-level назначения и сотруднику показываем
    только его пункты."""
    items = _hyp_items_map(t)
    if not items:
        return [], False
    tree = _tree_raw(t)
    has_item_asg = any([str(a).strip() for a in (it.get('assignees') or []) if str(a).strip()]
                       for it in items.values())
    if not has_item_asg:
        return [], False  # назначений на уровне пунктов нет -> полный вывод
    # если сотрудник прямо назван у гипотезы-родителя — не фильтруем
    for it in items.values():
        if not str(it.get('parent', '') or '').strip() and eid in [str(a).strip() for a in (it.get('assignees') or [])]:
            return [], False
    res = []
    for hid, it in items.items():
        asg = [str(a).strip() for a in (it.get('assignees') or []) if str(a).strip()]
        if eid not in asg:
            continue
        pid = str(it.get('parent', '') or '').strip() or _hyp_parent_of(tree, hid)
        res.append({'item': it, 'parent': pid})
    return res, True


def _task_repr(t):
    hyp_list = []
    raw_hyps = _tree_raw(t)
    for h in raw_hyps:
        if not isinstance(h, dict) or h.get('kind') != 'hypothesis':
            continue
        hid = h.get('id', '')
        jobs = []
        for tk in _job_children(raw_hyps, hid):
            jobs.append({
                'id': tk.get('id', ''),
                'title': (tk.get('title') or '')[:200],
                'status': tk.get('status', 'planned'),
                'status_label': JOB_STATUS_LABELS.get(tk.get('status', 'planned'), '⏳'),
                'assignees': [str(a).strip() for a in (tk.get('assignees') or []) if str(a).strip()],
            })
        hyp_list.append({
            'id': hid,
            'title': (h.get('title') or '')[:200],
            'status': h.get('status', 'planned'),
            'status_label': HYP_STATUS_LABELS.get(h.get('status', 'planned'), ''),
            'assignees': [str(a).strip() for a in (h.get('assignees') or []) if str(a).strip()],
            'jobs': jobs,
        })
    # вложенный формат: [{..., tasks:[...]}] без kind
    if not hyp_list:
        for h in raw_hyps:
            if not isinstance(h, dict) or h.get('kind'):
                continue
            hid = h.get('id', '')
            ch = h.get('tasks')
            if not isinstance(ch, list):
                continue
            jobs = [{
                'id': tk.get('id', ''),
                'title': (tk.get('title') or '')[:200],
                'status': tk.get('status', 'planned'),
                'status_label': JOB_STATUS_LABELS.get(tk.get('status', 'planned'), '⏳'),
                'assignees': [str(a).strip() for a in (tk.get('assignees') or []) if str(a).strip()],
            } for tk in ch if isinstance(tk, dict)]
            hyp_list.append({
                'id': hid,
                'title': (h.get('title') or '')[:200],
                'status': h.get('status', 'planned'),
                'status_label': HYP_STATUS_LABELS.get(h.get('status', 'planned'), ''),
                'assignees': [str(a).strip() for a in (h.get('assignees') or []) if str(a).strip()],
                'jobs': jobs,
            })
    return {
        'task_id': t.get('id', ''),
        'name': t.get('name', ''),
        'icon': t.get('icon', '📋'),
        'status': t.get('status', 'active'),
        'status_label': TASK_STATUS_LABELS.get(t.get('status', 'active'), ''),
        'start_date': t.get('start_date', ''),
        'deadline': t.get('deadline', ''),
        'description': (t.get('description') or '')[:2000],
        'tags': list(t.get('tags') or []),
        'is_urgent': bool(t.get('is_urgent')),
        'hypotheses': hyp_list,
    }


def _in_vacation(e, dk):
    """PATCH v1.0.9: сотрудник в отпуске/не на работе на дату?"""
    try:
        for v in (e.get('vacations') or []):
            if (v.get('from') or '9999') <= dk <= (v.get('to') or '0000'):
                return True
    except Exception:
        return False
    return False


def _collect(db, dk, scope='all', sort='default', hide_done=False):
    """scope: 'all' — все назначенные задачи; 'logged' — только с отметкой (лог)
    на выбранную дату (PATCH v1.0.7).
    PATCH v1.0.8: sort — порядок задач у сотрудника; hide_done — скрывать пункты,
    по которым уже поставлена отметка о выполнении.
    PATCH v1.0.9: item-level назначения учитываются и в плоском формате дерева
    (kind/parent); отметка (лог) с hyp_item_id засчитывается и по родительской
    гипотезе; добавлены флаги vacation/done_by_tree, last_log_date и статусы
    пунктов my_status/done для чекбоксов «готово из плагина»."""
    if sort not in ('default', 'deadline', 'urgent', 'name'):
        sort = 'default'
    data = db.load_all()
    employees = data.get('employees') or []
    tasks = data.get('tasks') or []
    logs = data.get('log') or []
    active_tasks = [t for t in tasks if _task_active_on(t, dk)]
    today_s = date.today().strftime('%Y-%m-%d')
    rows = []
    for e in employees:
        if e.get('fired'):
            continue
        eid = e.get('id', '')
        vac = _in_vacation(e, dk)
        my = []
        for t in active_tasks:
            if eid not in (t.get('assignees') or []):
                continue
            rep = _task_repr(t)
            # ---- фильтрация по гипотезе/заданию (item-level assignees) ----
            # PATCH v1.0.9: раньше фильтровались только вложенные деревья
            # ({hyp, tasks:[...]}) — плоский формат [{kind,parent}] молча
            # показывал все пункты. Теперь единый набор id для обоих форматов.
            items_map = _hyp_items_map(t)
            has_item_asg = any([str(a).strip() for a in (it.get('assignees') or [])
                                if str(a).strip()] for it in items_map.values())
            named_at_root = any(
                (not str(it.get('parent', '') or '').strip()) and
                (h.get('kind') == 'hypothesis' or not h.get('kind')) and
                eid in [str(a).strip() for a in (it.get('assignees') or [])]
                for hid, it in items_map.items() for h in [it])
            keep_ids = set()
            if has_item_asg and not named_at_root:
                for hid, it in items_map.items():
                    if eid in [str(a).strip() for a in (it.get('assignees') or [])]:
                        keep_ids.add(hid)
            filtered = bool(has_item_asg and not named_at_root)
            if filtered:
                kept_hyps = []
                for h in rep['hypotheses']:
                    hj = [j for j in h['jobs'] if j['id'] in keep_ids]
                    if h['id'] in keep_ids or hj:
                        h = dict(h)
                        h['jobs'] = hj
                        kept_hyps.append(h)
                if not kept_hyps:
                    continue  # сотруднику не назначен ни один пункт этой задачи
                rep['hypotheses'] = kept_hyps
                rep['filtered'] = True
            # PATCH v1.0.9: статус пункта для сотрудника = последний его лог
            # по этому пункту; если пункт закрыт в самом дереве (done/failed) —
            # считаем закрытым для всех.
            for h in rep['hypotheses']:
                h['my_status'] = _last_status_for(logs, eid, rep['task_id'], h['id'])
                if h['status'] in ('done', 'failed'):
                    h['done'] = True
                elif h['my_status'] == 'done':
                    h['done'] = True
                else:
                    h['done'] = False
                for j in h['jobs']:
                    j['my_status'] = _last_status_for(logs, eid, rep['task_id'], j['id'])
                    j['done'] = (j['status'] in ('done', 'failed')) or (j['my_status'] == 'done')
            # открытые пункты сотрудника
            open_items = []
            for h in rep['hypotheses']:
                if h['status'] in ('done', 'failed') or h.get('done'):
                    continue
                for j in h['jobs']:
                    if j.get('done'):
                        continue
                    if filtered and j['id'] not in keep_ids:
                        continue
                    open_items.append({'id': j['id'], 'title': j['title'],
                                       'hyp_id': h['id'], 'hyp_title': h['title']})
            rep['open_items'] = open_items
            # часы/отметки сотрудника по задаче на эту дату
            emp_task_logs = [l for l in logs if (l.get('employee_id') or '') == eid
                             and l.get('task_id') == rep['task_id']]
            day_logs = [l for l in emp_task_logs if (l.get('date') or '') == dk]
            rep['logged_hours'] = round(sum(_norm_hours(l.get('hours')) for l in day_logs), 2)
            rep['logged'] = bool(day_logs)
            _ld = [str(l.get('date') or '') for l in emp_task_logs if l.get('date')]
            rep['last_log_date'] = max(_ld) if _ld else ''
            rep['overdue'] = bool(rep['deadline'] and rep['deadline'] < today_s)
            rep['vacation'] = vac
            # PATCH v1.0.9: если все видимые пункты закрыты прямо в дереве —
            # задача считается выполненной даже без логов (для hide_done)
            vis_jobs = [j for h in rep['hypotheses'] for j in h['jobs']]
            if filtered and vis_jobs:
                rep['done_by_tree'] = all(j['status'] in ('done', 'failed') for j in vis_jobs)
            else:
                rep['done_by_tree'] = False
            # PATCH v1.0.7: режим «Отмеченные на сегодня» — только logged
            if scope == 'logged' and not rep['logged']:
                continue
            # PATCH v1.0.8: скрыть выполненные (есть отметка на дату / закрыто дерево)
            if hide_done and (rep['logged'] or rep['done_by_tree']):
                continue
            my.append(rep)
        if not my:
            continue
        if sort == 'deadline':
            my.sort(key=lambda x: (x.get('deadline') or '9999-99-99',
                                   (x.get('name') or '').lower()))
        elif sort == 'urgent':
            my.sort(key=lambda x: (not x.get('is_urgent'),
                                   x.get('deadline') or '9999-99-99',
                                   (x.get('name') or '').lower()))
        elif sort == 'name':
            my.sort(key=lambda x: (x.get('name') or '').lower())
        else:
            my.sort(key=lambda x: (
                {'active': 0, 'paused': 1}.get(x.get('status', 'active'), 2),
                x.get('deadline', '9999-99-99'),
                (x.get('name') or '').lower(),
            ))
        rows.append({
            'employee_id': eid,
            'employee_name': e.get('name', eid),
            'employee_color': e.get('color', '#888'),
            'department': e.get('department', ''),
            'vacation': vac,  # PATCH v1.0.9: бейдж «в отпуске» на дату
            'tasks_count': len(my),
            'logged_count': sum(1 for x in my if x['logged']),
            'logged_hours': round(sum(x['logged_hours'] for x in my), 2),
            'tasks': my,
        })
    rows.sort(key=lambda x: (-x['tasks_count'], (x.get('employee_name') or '').lower()))
    totals_logged = sum(r['logged_count'] for r in rows)
    totals_hours = round(sum(r['logged_hours'] for r in rows), 2)
    return {
        'date': dk,
        'scope': scope,
        'sort': sort,
        'hide_done': bool(hide_done),
        'employees': rows,
        'totals': {
            'employees_with_tasks': len(rows),
            'tasks_assignments': sum(r['tasks_count'] for r in rows),
            'logged_assignments': totals_logged,
            'logged_hours': totals_hours,
        },
    }


def _build_xlsx(payload, sel=None):
    """sel — опциональный словарь {employee_id: [task_id, ...]}: ограничивает
    выгрузку только выбранными пользователем строками (PATCH v1.0.7)."""
    wb = Workbook()
    ws = wb.active
    ws.title = 'Назначено на день'
    scope_lbl = 'отмеченные на сегодня' if payload.get('scope') == 'logged' else 'все задачи'
    ws.cell(1, 1, f"Назначено на день ({scope_lbl}): " + payload['date']).font = Font(bold=True, size=14)
    ws.merge_cells('A1:H1')
    hr = 3
    hdr_fill = PatternFill('solid', fgColor='FF2C3E50')
    hdr_font = Font(bold=True, color='FFFFFFFF')
    headers = ['Сотрудник', 'Отдел', 'Задача', 'Статус', 'Дедлайн', 'Часы за день',
               'Описание', 'Гипотезы / Задания']
    widths = [26, 18, 40, 14, 12, 12, 50, 50]
    for ci, (lbl, w) in enumerate(zip(headers, widths), 1):
        c = ws.cell(hr, ci, lbl)
        c.font = hdr_font
        c.fill = hdr_fill
        c.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.column_dimensions[get_column_letter(ci)].width = w
    ok_fill = PatternFill('solid', fgColor='FFEAF7F0')
    r = hr + 1
    for emp in payload['employees']:
        eid = emp['employee_id']
        allow = None if not sel else set(sel.get(eid) or [])
        first = True
        for t in emp['tasks']:
            if allow is not None and t['task_id'] not in allow:
                continue  # PATCH v1.0.7: не выбран чекбоксом — не выгружаем
            ws.cell(r, 1, emp['employee_name'] if first else '')
            ws.cell(r, 2, emp['department'] if first else '')
            ws.cell(r, 3, (('✅ ' if t.get('logged') else '') +
                           ('⏰ ' if t.get('overdue') else '') +
                           ((t['icon'] + ' ') if t['icon'] else '') + t['name']))
            ws.cell(r, 4, t['status_label'])
            ws.cell(r, 5, t['deadline'])
            ws.cell(r, 6, t.get('logged_hours', 0))
            ws.cell(r, 7, t['description'])
            hyp_lines = []
            for h in t.get('hypotheses', []):
                hyp_lines.append('🧪 ' + h['title'] + '  [' + h['status_label'] + ']')
                for j in h.get('jobs', []):
                    hyp_lines.append('    📌 ' + j['title'] + '  [' + j['status_label'] + ']')
            if t.get('filtered'):
                hyp_lines.insert(0, '(показаны только пункты, назначенные сотруднику)')
            ws.cell(r, 8, chr(10).join(hyp_lines))
            for ci in (3, 4, 5, 6, 7, 8):
                ws.cell(r, ci).alignment = Alignment(horizontal='left', vertical='top', wrap_text=True)
            if t.get('logged'):
                for ci in range(1, 9):
                    ws.cell(r, ci).fill = ok_fill
            first = False
            r += 1
        if r > hr + 1 and not first:
            r += 1
    out = BytesIO()
    wb.save(out)
    out.seek(0)
    return out


