      '<td>'+esc(t.icon||'📋')+' '+esc(t.name)+(t.is_urgent?' <span class="badge urg">🚨</span>':'')+(t.filtered?' <span class="badge flt">мои пункты</span>':'')+'</td>'+
      '<td><span class="badge '+statusCls(t.status)+'">'+esc(t.status_label)+'</span></td>'+
