function hypView(){
  var byHyp={};
  DATA.employees.forEach(function(e){
    e.tasks.forEach(function(t){
      (t.hypotheses||[]).forEach(function(h){
        var key=h.id||h.title;
        if(!byHyp[key])byHyp[key]={title:h.title,label:h.status_label,list:[]};
        h.jobs.forEach(function(j){
          if(j.assignees&&j.assignees.length&&j.assignees.indexOf(e.employee_id)<0)return;
          byHyp[key].list.push({emp:e,t:t,j:j});
        });
        if(!(h.jobs||[]).length)byHyp[key].list.push({emp:e,t:t,j:null});
      });
    });
  });
  return Object.keys(byHyp).map(function(k){
    var g=byHyp[k];
    var items=g.list.map(function(x){
      var checked=sel[x.emp.employee_id]&&sel[x.emp.employee_id][x.t.task_id]?' checked':'';
      return '<div class="hyp-task-row"><input type="checkbox" class="tsel" data-eid="'+esc(x.emp.employee_id)+'" data-tid="'+esc(x.t.task_id)+'"'+checked+'>'+
        '<span class="hyp-ico">'+esc(x.j?x.j.status_label:g.label)+'</span>'+
        '<span class="hyp-task-name">'+esc(x.j?x.j.title:x.t.name)+' <span class="meta">— '+esc(x.emp.employee_name)+'</span></span></div>';
    }).join('');
    return '<div class="hyp-group"><div class="hyp-group-title">🧪 '+esc(g.title)+' <span class="meta">'+esc(g.label)+'</span></div>'+items+'</div>';
  }).join('');
}
