function applyDefaults(){
  /* при первой загрузке дня: в режиме «отмеченные» всё выбрано по умолчанию,
     в режиме «все задачи» — выбраны только отмеченные (удобно для сводки дня) */
  var key=selKey();
  if(sel._key===key)return;
  sel={_key:key};
  DATA.employees.forEach(function(e){
    sel[e.employee_id]={};
    e.tasks.forEach(function(t){
      sel[e.employee_id][t.task_id]=(st.scope==='logged')?true:!!t.logged;
    });
  });
}
