def _ensure_plugin_asset_route(app):
    """PATCH v1.0.11-fix: общий роут /plugins-assets/<name>.js.

    В базе v1.0.0 этот маршрут нигде не объявлен, поэтому тег
    <script src="/plugins-assets/assigned_today.js"> в tracker.html
    давал 404 — плагин «Назначено на день» не регистрировался в меню.
    Роут отдаёт JS по имени плагина (только [a-z0-9_]), 404 если файла нет.
    Регистрируется один раз — безопасно при перезагрузке модуля."""
    try:
        if getattr(app, '_trk_plugins_assets_route', False):
            return
    except Exception:
        return
    from flask import send_file as _sf
    from pathlib import Path as _P

    @app.route('/plugins-assets/<name>.js', methods=['GET'])
    def _plugins_assets_js(name):
        import re as _re
        if not _re.fullmatch(r'[A-Za-z0-9_]+', name or ''):
            return ('not found', 404)
        f = _P(__file__).resolve().parent / (name + '.py')
        if not f.exists():
            return ('not found', 404)
        try:
            ns = {'__name__': 'plugin_' + name, '__file__': str(f)}
            exec(compile(f.read_text(encoding='utf-8-sig'), str(f), 'exec'), ns)
            js = ns.get('_JS') or ''
        except Exception as e:
            print('[plugins-assets] %s: %s' % (name, e))
            return ('not found', 404)
        if not js:
            return ('not found', 404)
        return app.response_class(js, mimetype='application/javascript',
                                  headers={'Cache-Control': 'no-store'})

    try:
        app._trk_plugins_assets_route = True
    except Exception:
        pass


def register(app, db, hooks):
    print(f'[assigned_today] v{__version__} · {__description__}')

    def _auth():
        try:
            from auth import current_user, user_has
            u = current_user(db)
            if not u:
                return None
            if u.get('role') == 'admin':
                return u
            if user_has(db, u, 'tab.stats') or user_has(db, u, 'tab.summary'):
                return u
        except Exception:
            pass
        return None

    @app.route('/plugins-assets/assigned_today.js', methods=['GET'])
    def _at_js():
        return app.response_class(_JS, mimetype='application/javascript')

    @app.route('/plugins/assigned_today/', methods=['GET'])
    def _at_page():
        if not _auth():
            return redirect('/login')
        try:
            from auth import ensure_csrf
            tok = ensure_csrf() or ''
        except Exception:
            tok = ''
        return Response(_PAGE_HTML.replace('__CSRF_TOKEN__', tok), mimetype='text/html')

    @app.route('/api/plugins/assigned_today/data', methods=['GET'])
    def _at_data():
        if not _auth():
            return jsonify({'success': False, 'error': 'forbidden'}), 403
        dk = (request.args.get('date') or '').strip()
        if not _valid_date(dk):
            dk = date.today().strftime('%Y-%m-%d')
        scope = (request.args.get('scope') or 'all').strip().lower()
        if scope not in ('all', 'logged'):
            scope = 'all'
        sort = (request.args.get('sort') or 'default').strip().lower()
        hide_done = (request.args.get('hide_done') or '').strip() in ('1', 'true', 'yes')
        try:
            payload = _collect(db, dk, scope, sort, hide_done)
            payload['success'] = True
            return jsonify(payload)
        except Exception as e:
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'error': str(e)[:200]}), 500

    @app.route('/api/plugins/assigned_today/mark_item', methods=['POST'])
    def _at_mark_item():
        """PATCH v1.0.9: чекбокс «Готово» по пункту гипотезы/заданию прямо из
        плагина. Создаёт (или обновляет) work_log сотрудника на выбранную дату
        с hyp_item_id; done=false снимает отметку (удаляет такой лог)."""
        u = _auth()
        if not u:
            return jsonify({'success': False, 'error': 'forbidden'}), 403
        try:
            j = request.get_json(force=True, silent=True) or {}
            eid = str(j.get('employee_id') or '').strip()
            tid = str(j.get('task_id') or '').strip()
            item = str(j.get('hyp_item_id') or '').strip()
            dk = str(j.get('date') or '').strip()
            done = bool(j.get('done'))
            if not (eid and tid and item and _valid_date(dk)):
                return jsonify({'success': False, 'error': 'некорректальные данные'}), 400
            # право ставить отметку: только назначенный сотрудник или admin
            my_uid = str(u.get('employee_id') or '').strip() or str(u.get('username') or '').strip()
            if u.get('role') != 'admin' and my_uid != eid:
                return jsonify({'success': False, 'error': 'можно отмечать только себя'}), 403
            data = db.load_all()
            task = next((t for t in (data.get('tasks') or []) if t.get('id') == tid), None)
            if not task:
                return jsonify({'success': False, 'error': 'задача не найдена'}), 404
            emp = next((e for e in (data.get('employees') or []) if e.get('id') == eid), None)
            if not emp:
                return jsonify({'success': False, 'error': 'сотрудник не найден'}), 404
            items_map = _hyp_items_map(task)
            if item not in items_map:
                return jsonify({'success': False, 'error': 'пункт гипотезы не найден'}), 404
            logs = data.get('log') or []
            ex = [l for l in logs if (l.get('employee_id') or '') == eid
                  and l.get('task_id') == tid and (l.get('date') or '') == dk
                  and (l.get('hyp_item_id') or '') == item]
            if not done:
                for l in ex:
                    try:
                        db.delete_log(l['id'])
                    except Exception:
                        pass
                return jsonify({'success': True, 'action': 'unmarked'})
            if ex:
                l0 = ex[0]
                pl = dict(l0)
                pl['status'] = 'done'
                db.upsert_log(l0['id'], pl)
            else:
                db.upsert_log(None, {
                    'employee_id': eid, 'task_id': tid, 'date': dk,
                    'hours': 0, 'comment': '✔ Готово (Назначено на день)',
                    'status': 'done', 'link': '',
                    'extra_data_json': '[]', 'orders_json': '[]', 'links_json': '[]',
                    'hyp_item_id': item,
                })
            return jsonify({'success': True, 'action': 'marked'})
        except Exception as e:
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'error': str(e)[:200]}), 500

    def _parse_sel(raw):
        """'emp1|task1,emp1|task2,...' -> {emp: [task,...]} (PATCH v1.0.7)."""
        out = {}
        try:
            for pair in (raw or '').split(','):
                if '|' not in pair:
                    continue
                eid, tid = pair.split('|', 1)
                eid, tid = eid.strip(), tid.strip()
                if eid and tid:
                    out.setdefault(eid, []).append(tid)
        except Exception:
            return None
        return out or None

    @app.route('/api/plugins/assigned_today/export.xlsx', methods=['GET'])
    def _at_export():
        if not _auth():
            return redirect('/login')
        if not _HAS_XLSX:
            return jsonify({'success': False, 'error': 'openpyxl не установлен'}), 503
        dk = (request.args.get('date') or '').strip()
        if not _valid_date(dk):
            dk = date.today().strftime('%Y-%m-%d')
        scope = (request.args.get('scope') or 'all').strip().lower()
        if scope not in ('all', 'logged'):
            scope = 'all'
        sort = (request.args.get('sort') or 'default').strip().lower()
        hide_done = (request.args.get('hide_done') or '').strip() in ('1', 'true', 'yes')
        sel = _parse_sel(request.args.get('sel'))
        try:
            payload = _collect(db, dk, scope, sort, hide_done)
            xlsx = _build_xlsx(payload, sel)
            tag = 'logged' if scope == 'logged' else 'all'
            fname = f'assigned_{dk}_{tag}.xlsx'
            return send_file(
                xlsx,
                mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                as_attachment=True, download_name=fname, max_age=0,
            )
        except Exception as e:
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'error': str(e)[:200]}), 500

    _ensure_plugin_asset_route(app)

    def on_startup(**ctx):
        print('[assigned_today] готов')

    hooks.on('on_startup', on_startup)
    # PATCH v1.0.11-fix: страховка — зарегистрировать роут сразу,
    # даже если событие on_startup уже миновал (hot-reload).
    try:
        _ensure_plugin_asset_route(app)
    except Exception as _e:
        print('[assigned_today] asset-route guard:', _e)
